 * The two policy kinds a limiter file can declare. Both keep one
 * independent state per key and expose the same three-step protocol the
 * simulator drives every policy through: `advance` a key's state to a
 * tick, `allow` asks whether a request at that tick would be let through,
 * and `record` commits one.
 */

/**
 * A token bucket. Tokens are tracked as an exact fraction with denominator
 * `per`, stored as `tokensNum = tokens * per`, so refilling by `refill`
 * tokens per `per` ticks over `dt` ticks is the exact integer addition
 * `refill * dt`, with no rounding.
 */
export class BucketPolicy {
  constructor(capacity, refill, per) {
    this.refill = refill
    this.per = per
    this.capacityNum = capacity * per
    this.states = new Map()
  }

  #state(key) {
    let state = this.states.get(key)
    if (!state) {
      state = { tokensNum: this.capacityNum, lastTick: null }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#state(key)
    if (state.lastTick === null) {
      state.lastTick = tick
      return
    }
    const dt = tick - state.lastTick
    if (dt > 0n) {
      state.tokensNum += this.refill * dt
      if (state.tokensNum > this.capacityNum) state.tokensNum = this.capacityNum
      state.lastTick = tick
    }
  }

  allow(key) {
    return this.#state(key).tokensNum >= this.per
  }

  record(key) {
    this.#state(key).tokensNum -= this.per
  }
}

/**
 * A sliding window. Remembers the ticks of the requests it recorded for a
 * key, in ascending order, and forgets the ones that have fallen out of
 * the window when advanced.
 */
export class WindowPolicy {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  #state(key) {
    let state = this.states.get(key)
    if (!state) {
      state = []
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const ticks = this.#state(key)
    const threshold = tick - this.span
    let drop = 0
    while (drop < ticks.length && ticks[drop] <= threshold) drop++
    if (drop > 0) ticks.splice(0, drop)
  }

  allow(key) {
    return BigInt(this.#state(key).length) < this.limit
  }

  record(key) {
    this.#state(key).push(this.states.get(key).at(-1))
  }
}
"}

