import { LimiterError } from './limiterError.js'
import { BucketPolicy, WindowPolicy } from './policies.js'

const NAME_RE = /^[A-Za-z0-9_.\/:-]+$/
const UINT_RE = /^(0|[1-9][0-9]*)$/

function parseUint(token, field, min) {
  if (!UINT_RE.test(token)) return null
  const value = BigInt(token)
  if (value < BigInt(min)) return null
  return value
}

function requireUint(token, field, min, line) {
  const value = parseUint(token, field, min)
  if (value === null) throw new LimiterError(line, `${field} must be an integer of at least ${min}`)
  return value
}

function requireName(token, kind, line) {
  if (!NAME_RE.test(token)) throw new LimiterError(line, `invalid ${kind} ${token}`)
  return token
}

/**
 * Runs a limiter file, given as its raw text, and returns the ordered
 * list of event verdicts plus the per-key and overall totals. Throws a
 * `LimiterError` at the first invalid line.
 */
export function simulate(input) {
  const rawLines = input.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()

  const policies = new Map() // name -> policy instance
  const routes = [] // { prefix, policyNames: [] }
  const events = []
  const summary = new Map() // key -> { allowed, denied }

  let firstEventSeen = false
  let lastTick = null

  const bumpSummary = (key, allowed) => {
    let entry = summary.get(key)
    if (!entry) {
      entry = { allowed: 0, denied: 0 }
      summary.set(key, entry)
    }
    if (allowed) entry.allowed++
    else entry.denied++
  }

  for (let i = 0; i < rawLines.length; i++) {
    const line = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (firstEventSeen) throw new LimiterError(line, 'declarations must come before the first event')
    }

    if (directive === 'bucket') {
      if (tokens.length !== 5) throw new LimiterError(line, 'expected bucket <name> <capacity> <refill> <per>')
      const name = requireName(tokens[1], 'policy name', line)
      if (policies.has(name)) throw new LimiterError(line, `policy ${name} is declared twice`)
      const capacity = requireUint(tokens[2], 'capacity', 1, line)
      const refill = requireUint(tokens[3], 'refill', 0, line)
      const per = requireUint(tokens[4], 'per', 1, line)
      policies.set(name, new BucketPolicy(capacity, refill, per))
    } else if (directive === 'window') {
      if (tokens.length !== 4) throw new LimiterError(line, 'expected window <name> <limit> <span>')
      const name = requireName(tokens[1], 'policy name', line)
      if (policies.has(name)) throw new LimiterError(line, `policy ${name} is declared twice`)
      const limit = requireUint(tokens[2], 'limit', 0, line)
      const span = requireUint(tokens[3], 'span', 1, line)
      policies.set(name, new WindowPolicy(limit, span))
    } else if (directive === 'route') {
      if (tokens.length < 3) throw new LimiterError(line, 'expected route <prefix> <policy>...')
      const prefix = requireName(tokens[1], 'route prefix', line)
      if (routes.some((r) => r.prefix === prefix)) throw new LimiterError(line, `prefix ${prefix} is routed twice`)
      const policyNames = tokens.slice(2)
      for (const name of policyNames) {
        if (!policies.has(name)) throw new LimiterError(line, `unknown policy ${name}`)
      }
      routes.push({ prefix, policyNames })
    } else if (directive === 'event') {
      if (tokens.length !== 3) throw new LimiterError(line, 'expected event <tick> <key>')
      firstEventSeen = true
      const tick = requireUint(tokens[1], 'tick', 0, line)
      const key = requireName(tokens[2], 'key', line)
      if (lastTick !== null && tick < lastTick) {
        throw new LimiterError(line, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick

      let matched = null
      for (const route of routes) {
        if (key.startsWith(route.prefix)) {
          if (!matched || route.prefix.length > matched.prefix.length) matched = route
        }
      }

      if (!matched) {
        events.push({ tick, key, allowed: true, deniedBy: null })
        bumpSummary(key, true)
        continue
      }

      const routePolicies = matched.policyNames.map((name) => ({ name, policy: policies.get(name) }))
      for (const { policy } of routePolicies) policy.advance(key, tick)

      let deniedBy = null
      for (const { name, policy } of routePolicies) {
        if (!policy.allow(key)) {
          deniedBy = name
          break
        }
      }

      const allowed = deniedBy === null
      if (allowed) {
        for (const { policy } of routePolicies) policy.record(key, tick)
      }

      events.push({ tick, key, allowed, deniedBy })
      bumpSummary(key, allowed)
    } else {
      throw new LimiterError(line, `unknown directive ${directive}`)
    }
  }

  return { events, summary }
}
"}

