      lines.push(`${key} allowed=${allowed} denied=${denied}`)
      totalAllowed += allowed
      totalDenied += denied
    }
    lines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
  }

  process.stdout.write(lines.length ? lines.join('\n') + '\n' : '')
}

